import{_ as d,o as e,c as o,a6 as a}from"./chunks/framework.BoFLe3f3.js";const m=JSON.parse('{"title":"版本能力矩阵：15.x → 16.3","description":"把 Next.js 15.x 与 16.3 的关键行为差异整理成可验证的矩阵：每行都给出迁移动作与验证方式，避免凭印象升级。","frontmatter":{"title":"版本能力矩阵：15.x → 16.3","description":"把 Next.js 15.x 与 16.3 的关键行为差异整理成可验证的矩阵：每行都给出迁移动作与验证方式，避免凭印象升级。"},"headers":[],"relativePath":"version-matrix.md","filePath":"version-matrix.md","lastUpdated":1792735573000}'),r={name:"version-matrix.md"};function c(i,t,s,n,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="版本能力矩阵" tabindex="-1">版本能力矩阵 <a class="header-anchor" href="#版本能力矩阵" aria-label="Permalink to &quot;版本能力矩阵&quot;">​</a></h1><p>单版本教程最容易出现的误区，是「我记得 15 不是这样的」。这一页把关键差异压成一张可核对的表：<strong>变化点、迁移动作、怎么验证</strong>。</p><table tabindex="0"><thead><tr><th>能力</th><th>15.x 行为</th><th>16.3 行为</th><th>迁移动作</th><th>验证方式</th></tr></thead><tbody><tr><td>打包器</td><td>Webpack 为主，Turbopack 可选</td><td>Turbopack 默认，持久化磁盘缓存</td><td>移除自定义 Webpack 配置，改用 Turbopack 等价配置</td><td><code>next build</code> 日志确认打包器；对比构建耗时</td></tr><tr><td>请求拦截</td><td><code>middleware.ts</code>（Edge 为主）</td><td><code>proxy.ts</code>（Node 运行时）</td><td>重命名文件与导出函数，检查 matcher</td><td>访问受保护路径，确认拦截仍生效</td></tr><tr><td>动态参数</td><td><code>params</code> / <code>searchParams</code> 同步</td><td>异步，需要 <code>await</code></td><td>所有页面与布局改为 <code>await params</code></td><td>类型检查 + 直接访问动态路由</td></tr><tr><td>部分预渲染</td><td><code>experimental.ppr</code> 开关</td><td><code>cacheComponents</code> 模型</td><td>移除实验开关，按 Cache Components 拆分外壳与动态区</td><td>构建输出是否产出静态 shell</td></tr><tr><td>缓存默认值</td><td>动态为主，显式 opt-in</td><td>动态默认 + <code>use cache</code> 显式缓存</td><td>审计所有取数函数，补 <code>cacheTag</code> 与失效点</td><td>写入后读取是否立即更新</td></tr><tr><td>Edge Runtime</td><td>支持</td><td>废弃，回归 Node 运行时</td><td>移除 <code>export const runtime = &quot;edge&quot;</code></td><td>构建无相关警告；检查依赖的 Node API</td></tr><tr><td>SSR 实现</td><td>Web Streams</td><td>Node.js 原生流</td><td>通常无需改代码，检查自定义流适配</td><td>压测下 TTFB 与吞吐</td></tr><tr><td>即时导航</td><td>预取 + loading</td><td>Cache Components + Partial Prefetching + <code>instant()</code> 断言</td><td>拆分外壳，补 Playwright <code>instant()</code></td><td>点击后 100ms 内是否出现外壳</td></tr><tr><td>React Compiler</td><td>需手动开启</td><td>实验性 Rust 实现可选</td><td>在基线稳定后灰度开启</td><td>同一性能预算前后对比</td></tr><tr><td>类型检查</td><td>tsc</td><td>可选 TypeScript 7 原生移植</td><td>在 CI 增加开关与耗时对比</td><td>类型错误是否一致、耗时是否下降</td></tr><tr><td>AI 开发链路</td><td>无统一入口</td><td><code>AGENTS.md</code> + first-party Skills + Actionable Errors</td><td>接入 <code>AGENTS.md</code>，统一错误修复提示</td><td>新成员按文档能否独立启动</td></tr></tbody></table><h2 id="升级前的三个检查" tabindex="-1">升级前的三个检查 <a class="header-anchor" href="#升级前的三个检查" aria-label="Permalink to &quot;升级前的三个检查&quot;">​</a></h2><ol><li><strong>先跑内容门禁与构建</strong>：<code>pnpm check:content &amp;&amp; pnpm docs:build</code>，确认现有内容没有依赖旧行为。</li><li><strong>列出所有隐式缓存假设</strong>：搜索 <code>&quot;use cache&quot;</code>、<code>fetch(</code>、<code>cookies()</code>、<code>headers()</code>，逐个确认缓存键与失效点。</li><li><strong>准备回滚</strong>：保留上一版本产物与部署配置，记录回滚耗时；升级不是一次性动作。</li></ol><h2 id="常见误判" tabindex="-1">常见误判 <a class="header-anchor" href="#常见误判" aria-label="Permalink to &quot;常见误判&quot;">​</a></h2><ul><li>「16 默认全静态」——错。默认是动态，静态与缓存都需要显式声明。</li><li>「proxy.ts 只是改名」——错。运行时与执行边界都变了，鉴权不能只靠它。</li><li>「开了 Turbopack 就不用管构建配置」——错。自定义 loader/plugin 仍需要等价迁移。</li></ul><p>对应章节：<a href="/nextjs-tutorial-site/chapters/01-introduction/basics">第 1 章 · 基础</a>、<a href="/nextjs-tutorial-site/chapters/05-caching/advanced">第 5 章 · 缓存</a>、<a href="/nextjs-tutorial-site/chapters/09-route-handlers/advanced">第 9 章 · proxy.ts</a>、<a href="/nextjs-tutorial-site/chapters/13-testing-deployment/practice">第 13 章 · 部署</a>。</p>',8)])])}const u=d(r,[["render",c]]);export{m as __pageData,u as default};
